#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Prove that a fix round changed documentation only, before the architect accepts it without a
# review. Every fix round of urbanexteriors plan 001 and two in liliiachaika (031, 032) were
# accepted on the architect's reading; this makes the reading a check.
#   ./scripts/orca/docs-only.sh <worktree> <commit before the fix> <commit after the fix>
# Documentation is `*.md` `docs/*` (.orca-setup.json `docs_only`).
# Prints "DOCS ONLY" or "NOT DOCS ONLY: <files>" (exit 1).
set -uo pipefail

wt=${1:?usage: scripts/orca/docs-only.sh <worktree> <before> <after>}
before=${2:?usage: scripts/orca/docs-only.sh <worktree> <before> <after>}
after=${3:?usage: scripts/orca/docs-only.sh <worktree> <before> <after>}

if ! files=$(git -C "$wt" diff --name-only "$before" "$after"); then
  echo "NOT DOCS ONLY: git diff failed"
  exit 1
fi
other=()
while IFS= read -r file; do
  [ -n "$file" ] || continue
  case "$file" in
    *.md) ;;
    docs/*) ;;
    *) other+=("$file") ;;
  esac
done <<<"$files"
if [ -z "$files" ]; then
  echo "NOT DOCS ONLY: no change between $before and $after"
  exit 1
fi
if [ "${#other[@]}" -eq 0 ]; then
  echo "DOCS ONLY"
else
  echo "NOT DOCS ONLY: ${other[*]}"
  exit 1
fi
